import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a Morales-Luna component, conditional linear term,
    skewed quartic, sinusoidal modulation, and distance-based interaction. Domain: [-5, 5]^N.

    f(x) = 0.3*morales_luna(x) + cond_linear(x) + 0.2*skewedQuartic(x) + sin_term(x) + distance_interaction(x)
    """
    n = len(x)

    def morales_luna(x):
        z = x + 0.1
        return np.sum(z**4 - 16*z**2 + 5*z)

    def cond_linear(x):
        norm_x = np.linalg.norm(x)
        if norm_x >= 2 and norm_x <= 4:
            return 0.5 * np.sum(x)
        else:
            return 0.0

    def skewedQuartic(x):
        return np.sum(x**4) + 0.1 * np.sum(x)

    def sin_term(x):
        return 0.1 * np.sum(np.sin(x) * np.arange(1, n+1))

    def distance_interaction(x) :
         interaction_sum = 0.0
         for i in range(n):
             dist = np.linalg.norm(x[i] - x[(i + 1) % n])
             interaction_sum += dist**2
         return 0.05 * interaction_sum

    result = 0.3 * morales_luna(x) + cond_linear(x) + 0.2 * skewedQuartic(x) + sin_term(x) + distance_interaction(x)

    return result

description:
A synthetic benchmark function based on a radial basis function (RBF) kernel with linear and interaction terms, and a skewness-inducing component.

Formula:
f(x) = rbf_term(x) + linear_term(x) + interaction_term(x) + skewness_term(x)

where:
rbf_term(x) = exp(-gamma * ||x - center||^2), gamma = 0.1, center = [1, 1, ..., 1];
linear_term(x) = 0.2 * sum(x_i);
interaction_term(x) = 0.1 * sum(x_i * x_j for i < j);
skewness_term(x) = 0.0 if sum(x) < 0 else 0.2 * (sum(x)**2) * exp(-0.1 * np.linalg.norm(x));

This construction balances global structure (RBF), local variations (interaction terms), adjusted regressions (linear & interactions) and asymmetry.
